const require_runtime = require('./_virtual/_rolldown/runtime.cjs');
let _opentelemetry_api = require("@opentelemetry/api");

//#region src/telemetry.ts
/**
* Initialize telemetry using OpenTelemetry's global registry.
* If Otel providers are not initialized, operations will be no-ops automatically.
*/
function initTelemetry() {
	const tracer = _opentelemetry_api.trace.getTracer("@databricks/lakebase");
	const meter = _opentelemetry_api.metrics.getMeter("@databricks/lakebase");
	return {
		tracer,
		meter,
		tokenRefreshDuration: meter.createHistogram("lakebase.token.refresh.duration", {
			description: "Duration of OAuth token refresh operations",
			unit: "ms"
		}),
		queryDuration: meter.createHistogram("lakebase.query.duration", {
			description: "Duration of queries executed via pool.query",
			unit: "ms"
		}),
		poolErrors: meter.createCounter("lakebase.pool.errors", {
			description: "Connection pool errors by error code",
			unit: "1"
		})
	};
}
/**
* Attach pool-level metrics collection, error counting, and error logging.
*
* Uses observable gauges (pull model) for pool connection stats.
*
* @param pool - PostgreSQL connection pool
* @param telemetry - Telemetry instruments
* @param logger - Optional logger for error logging (silent if not provided)
*/
function attachPoolMetrics(pool, telemetry, logger) {
	const meter = telemetry.meter;
	const poolTotal = meter.createObservableGauge("lakebase.pool.connections.total", { description: "Total connections in the pool" });
	const poolIdle = meter.createObservableGauge("lakebase.pool.connections.idle", { description: "Idle connections in the pool" });
	const poolWaiting = meter.createObservableGauge("lakebase.pool.connections.waiting", { description: "Clients waiting for a connection" });
	poolTotal.addCallback((result) => result.observe(pool.totalCount));
	poolIdle.addCallback((result) => result.observe(pool.idleCount));
	poolWaiting.addCallback((result) => result.observe(pool.waitingCount));
	pool.on("error", (error) => {
		logger?.error("Connection pool error: %s (code: %s)", error.message, error.code);
		telemetry.poolErrors.add(1, { "error.code": error.code ?? "unknown" });
	});
}

//#endregion
exports.attachPoolMetrics = attachPoolMetrics;
exports.initTelemetry = initTelemetry;